package ec.edu.unl.sec.selfassessment.support;import ec.edu.unl.sec.selfassessment.application.*;import ec.edu.unl.sec.selfassessment.domain.*;import java.util.*;public class InMemorySelfAssessmentRepository implements SelfAssessmentRepository{public final Map<UUID,SelfAssessmentProcess> processes=new LinkedHashMap<>();public final List<ProcessAssignment> assigned=new ArrayList<>();public void save(SelfAssessmentProcess p,long expected){var old=processes.get(p.id());if(expected>=0&&(old==null||old.revision()!=expected))throw new IllegalStateException("STALE_PROCESS");processes.put(p.id(),p);}public Optional<SelfAssessmentProcess> find(UUID id){return Optional.ofNullable(processes.get(id));}public List<SelfAssessmentProcess> list(){return List.copyOf(processes.values());}public void saveAssignment(ProcessAssignment a){assigned.add(a);}public List<ProcessAssignment> assignments(UUID id){return assigned.stream().filter(a->a.processId().equals(id)).toList();}public void recordTransition(UUID a,ProcessState b,ProcessState c,UUID d,String e,UUID f,long g){}}
